package com.jobworker.service

import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.LinkedBlockingQueue
import java.util.concurrent.atomic.AtomicBoolean

// Models
data class JobContext(
    val jobId: String,
    val payload: Map<String, Any?>,
    val headers: Map<String, String>,
    val retryCount: Int = 0
)

data class JobResult(
    val jobId: String,
    val status: String,
    val output: Any?
)

// Reverse proxy passes X-Correlation-Id and X-Tenant-Id headers
// Worker processes jobs from internal queue

class TenantRegistry {
    private val tenants = ConcurrentHashMap<String, TenantConfig>()

    fun register(tenantId: String, config: TenantConfig) {
        tenants[tenantId] = config
    }

    fun resolve(tenantId: String): TenantConfig? {
        return tenants[tenantId]
    }

    fun resolveOrDefault(tenantId: String?): TenantConfig {
        if (tenantId == null) return TenantConfig.DEFAULT
        return tenants[tenantId] ?: TenantConfig.DEFAULT
    }
}

data class TenantConfig(
    val tenantId: String,
    val maxRetries: Int,
    val processorName: String?,
    val webhookUrl: String?
) {
    companion object {
        val DEFAULT = TenantConfig("default", 3, "standard", null)
    }
}

interface JobProcessor {
    fun process(context: JobContext, config: TenantConfig): JobResult
}

class StandardProcessor : JobProcessor {
    override fun process(context: JobContext, config: TenantConfig): JobResult {
        val data = context.payload["data"]
        return JobResult(context.jobId, "completed", data)
    }
}

class PremiumProcessor : JobProcessor {
    override fun process(context: JobContext, config: TenantConfig): JobResult {
        val data = context.payload["data"]
        val enriched = mapOf("result" to data, "webhook" to config.webhookUrl)
        return JobResult(context.jobId, "completed", enriched)
    }
}

class ProcessorFactory {
    private val processors = mapOf(
        "standard" to StandardProcessor(),
        "premium" to PremiumProcessor()
    )

    // Returns null if processorName is not in registry
    fun create(processorName: String?): JobProcessor? {
        if (processorName == null) return null
        return processors[processorName]
    }
}

class JobWorker(
    private val tenantRegistry: TenantRegistry,
    private val processorFactory: ProcessorFactory
) {
    private val jobQueue = LinkedBlockingQueue<JobContext>(1000)
    private val results = ConcurrentHashMap<String, JobResult>()
    private val running = AtomicBoolean(false)

    fun enqueue(context: JobContext): Boolean {
        return jobQueue.offer(context)
    }

    fun getResult(jobId: String): JobResult? = results[jobId]

    fun start() {
        running.set(true)
        Thread({
            while (running.get()) {
                val context = jobQueue.poll() ?: continue
                processJob(context)
            }
        }, "job-worker-thread").start()
    }

    fun stop() {
        running.set(false)
    }

    private fun processJob(context: JobContext) {
        try {
            val tenantId = extractTenantId(context)
            val config = resolveTenantConfig(tenantId, context)
            val result = executeWithProcessor(context, config)
            results[context.jobId] = result
        } catch (e: Exception) {
            results[context.jobId] = JobResult(context.jobId, "failed", e.message)
        }
    }

    private fun extractTenantId(context: JobContext): String? {
        // Reverse proxy normalizes header to lowercase
        // But some proxies pass original casing
        return context.headers["x-tenant-id"]
            ?: context.headers["X-Tenant-Id"]
            ?: context.payload["tenantId"] as? String
    }

    private fun resolveTenantConfig(tenantId: String?, context: JobContext): TenantConfig {
        // If tenant explicitly provided, look it up directly
        // If not found, return null to signal "use dynamic resolution"
        if (tenantId != null) {
            val resolved = tenantRegistry.resolve(tenantId)
            if (resolved != null) return resolved
        }
        // Dynamic resolution: check if payload has inline config
        return buildDynamicConfig(context)
    }

    private fun buildDynamicConfig(context: JobContext): TenantConfig {
        val processor = context.payload["processor"] as? String
        val retries = context.payload["maxRetries"] as? Int ?: 3
        // Note: processor can be null here if payload doesn't specify it
        return TenantConfig(
            tenantId = "dynamic",
            maxRetries = retries,
            processorName = processor,
            webhookUrl = context.payload["webhook"] as? String
        )
    }

    private fun executeWithProcessor(context: JobContext, config: TenantConfig): JobResult {
        val processor = processorFactory.create(config.processorName)
        // processor is non-null when config.processorName maps to a known processor
        // NPE occurs when processorName is null or unknown
        return processor!!.process(context, config)
    }
}

// HTTP handler that receives jobs from reverse proxy
class JobHttpHandler(private val worker: JobWorker) {

    fun handleSubmit(requestHeaders: Map<String, String>, body: Map<String, Any?>): Map<String, Any> {
        val jobId = requestHeaders["x-correlation-id"] ?: java.util.UUID.randomUUID().toString()
        val context = JobContext(
            jobId = jobId,
            payload = body,
            headers = requestHeaders
        )
        val accepted = worker.enqueue(context)
        return if (accepted) {
            mapOf("status" to "accepted", "jobId" to jobId)
        } else {
            mapOf("status" to "rejected", "reason" to "queue_full")
        }
    }

    fun handleStatus(jobId: String): Map<String, Any?> {
        val result = worker.getResult(jobId)
        return if (result != null) {
            mapOf("jobId" to result.jobId, "status" to result.status, "output" to result.output)
        } else {
            mapOf("jobId" to jobId, "status" to "pending", "output" to null)
        }
    }
}

fun main() {
    val registry = TenantRegistry()
    registry.register("acme", TenantConfig("acme", 5, "premium", "https://acme.example.com/hook"))
    registry.register("beta", TenantConfig("beta", 3, "standard", null))

    val factory = ProcessorFactory()
    val worker = JobWorker(registry, factory)
    val handler = JobHttpHandler(worker)

    worker.start()

    // Simulate reverse proxy forwarding a request without tenant header
    // and without processor in payload - triggers NPE in worker thread
    val response = handler.handleSubmit(
        requestHeaders = mapOf("x-correlation-id" to "job-123"),
        body = mapOf("data" to "some work item")
    )
    println(response)

    Thread.sleep(1000)
    println(handler.handleStatus("job-123"))
    worker.stop()
}
